@torch_op("aten::signbit", trace_only=True)
def aten_signbit(self: TensorType) -> BOOL:
    """signbit(Tensor self) -> Tensor"""

    if self.dtype == ir.DataType.BOOL:
        return op.ConstantOfShape(op.Shape(self), value=ir.tensor([False]))

