import torch.nn.functional as F

class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.conv = torch.nn.Conv2d(1, 4, 3, dilation=2)
        self.head = torch.nn.Conv2d(4, 1, 1)
    def forward(self, x):
        hidden = F.relu(self.conv(F.pad(x, (2, 2, 2, 2), mode='reflect')))
        return x - self.head(hidden)

import torch
import torch.nn.functional as F

class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.register_buffer('mean', torch.tensor([0.485, 0.456, 0.406]).view(1, 3, 1, 1))
        self.register_buffer('std', torch.tensor([0.229, 0.224, 0.225]).view(1, 3, 1, 1))
        self.conv = torch.nn.Conv2d(3, 6, 3, padding=1, bias=False)
        self.norm = torch.nn.BatchNorm2d(6)
    def forward(self, x):
        features = F.relu(self.norm(self.conv((x - self.mean) / self.std)))
        return features.mean(dim=(-2, -1))

import torch
import torch.nn.functional as F

class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.message = torch.nn.Linear(4, 4)
        self.update = torch.nn.Linear(8, 3)
    def forward(self, nodes, source, target):
        messages = F.relu(self.message(nodes.index_select(0, source)))
        aggregate = torch.zeros_like(nodes).index_add(0, target, messages)
        return self.update(torch.cat((nodes, aggregate), dim=-1))

